    private static readonly string ConfigPath = Path.Combine(
        Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), ".whisper", "charanim.json");

    public static CharAnim LoadOrCreate()
    {
        var anim = new CharAnim();
        var json = DefaultJson;
        if (File.Exists(ConfigPath))
        {
            try
            {
                var fileJson = File.ReadAllText(ConfigPath);
                if (!string.IsNullOrWhiteSpace(fileJson))
                {
                    using var test = JsonDocument.Parse(fileJson);
                    if (test.RootElement.TryGetProperty("fps", out _))
                        json = fileJson;
                }
            }
            catch {}
        }
        else
        {
            var dir = Path.GetDirectoryName(ConfigPath)!;
            Directory.CreateDirectory(dir);
            File.WriteAllText(ConfigPath, DefaultJson);
        }
        ParseJson(json, anim);
        return anim;
    }

    private static void ParseJson(string json, CharAnim anim)
    {
        using var doc = JsonDocument.Parse(json);
        anim.Fps = doc.RootElement.GetProperty("fps").GetInt32();
        anim._frames.Clear();
        foreach (var frame in doc.RootElement.GetProperty("frames").EnumerateArray())
        {
            var lines = new string[11];
            var arr = frame.EnumerateArray().ToArray();
            for (int i = 0; i < 11 && i < arr.Length; i++)
                lines[i] = arr[i].GetString() ?? "";
            anim._frames.Add(lines);
        }
    }

    public string[] GetFrame(int index)
    {
        if (_frames.Count == 0) return new string[11];
        return _frames[index % _frames.Count];
    }
